using System.Text.Json;
namespace InovaGed.Environment.Doctor.Quality;
public sealed class UatReadinessQualityCheck:IQualityCheck
{
 public string Name=>"UAT Readiness";
 public async Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext context,CancellationToken ct){var required=new[]{"database/migrations/2026_08_24_uat_go_live_readiness.sql","database/seeds/2026_08_uat_test_cases_seed.sql","InovaGed.Web/Controller/UatReadinessController.cs","InovaGed.Web/Views/UatReadiness/GoLiveChecklist.cshtml"};var missing=required.Where(x=>!File.Exists(Path.Combine(context.Root,x))).ToArray();var status=missing.Length==0?QualityStatus.Pass:QualityStatus.Fail;var result=new QualityFinding(Name,status,missing.Length==0?"Camada UAT, evidências e Go-Live disponível.":$"Artefatos ausentes: {string.Join(", ",missing)}",missing.Length==0?null:"Homologação não pode ser comprovada.",missing.Length==0?null:"Restaurar os artefatos UAT.",Resource:"/UatReadiness");var dir=Path.Combine(context.Root,"artifacts","uat");Directory.CreateDirectory(dir);var payload=new{generatedAtUtc=DateTimeOffset.UtcNow,status=status.ToString(),checks=required.Select(x=>new{resource=x,exists=File.Exists(Path.Combine(context.Root,x))})};await File.WriteAllTextAsync(Path.Combine(dir,"uat-readiness-report.json"),JsonSerializer.Serialize(payload,new JsonSerializerOptions{WriteIndented=true}),ct);var md=$"# UAT Readiness\n\n- **Status:** {status.ToString().ToUpperInvariant()}\n- **Gerado em:** {DateTimeOffset.UtcNow:O}\n\n"+string.Join("\n",required.Select(x=>$"- [{(File.Exists(Path.Combine(context.Root,x))?"x":" ")}] `{x}`"));await File.WriteAllTextAsync(Path.Combine(dir,"uat-readiness-report.md"),md,ct);return new[]{result};}
}
